import React from 'react';
import {magic} from '@utils';
import {Button} from '@ui';
import Image from './Image';
import Link from './Link';
import skeletonImage from '@styles/images/skeleton.jpg';
import s from './Card.scss';

const Card = ({skeleton, gift, onClick, button}) => {
  if (skeleton) {
    return (
      <div className={s.card}>
        <div className={s.title}>
          {'Подарочки загружаются'}
        </div>
        <Image src={skeletonImage} alt={'skeleton image'} />
        <div className={s.actions}>
          <Button color={'blue'}>{'Пум пум пум'}</Button>
          <Button color={'green'}>{'Пам пам пам'}</Button>
        </div>
      </div>
    );
  }

  return (
    <div className={s.card}>
      <div className={s.title}>
        {gift.name}
      </div>
      <Link
        href={gift.link}
        name={<Image src={gift.image} alt={gift.id} />}
      />
      <div className={s.actions}>
        <Link
          href={gift.link}
          name={<Button color={'blue'}>{'Подробнее'}</Button>}
        />
        {
          button.isAlreadyBooked ? (
            <div className={s.message}>
              {'Этот подарок уже дарит кто-то другой'}
            </div>
          ) : (
            <Button
              color={button.color}
              onClick={() => onClick(gift)}
              disabled={button.disabled}
            >
              {button.title}
            </Button>
          )
        }
      </div>
    </div>
  );
};

export default magic(Card, {styles: s});