import React from 'react';
import {magic} from '@utils';
import {onSnapshot, collection} from 'firebase/firestore';
import {db} from '../../firebase.ts';
import {Card} from '@ui';
import s from './style.scss';

const List = ({gifts, setGifts, bookGift, canBookedGifts, loading, setLoading, user}) => {
  React.useEffect(() => {
    setLoading(true);

    const unsubscribe = onSnapshot(collection(db, 'gifts'), (snapshot) => {
      const newGifts = snapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data()
      }));

      setGifts(newGifts);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  if (loading && !gifts.length) {
    return (
      <div className={s.container}>
        <div className={s.list}>
          {
            ['1', '2', '3', '4', '5'].map((val) => <Card key={val} skeleton={true} />)
          }
        </div>
      </div>
    );
  }

  return (
    <div className={s.container}>
      <div className={s.list}>
        {
          gifts.map((gift) => {
            const buttonProps = {
              color: 'green',
              title: 'Подарю это',
              isAlreadyBooked: false,
              disabled: !canBookedGifts
            };

            if (gift.bookedByUser) {
              if (user.email === gift.bookedByUser) {
                buttonProps.color = 'red';
                buttonProps.title = 'Отмена'
                buttonProps.disabled = false;
              } else {
                buttonProps.isAlreadyBooked = true;
              }
            }

            return (
              <Card
                gift={gift}
                key={gift.id}
                button={buttonProps}
                onClick={bookGift}
              />
            );
          })
        }
      </div>
    </div>
  );
};

const mapStore = ({GiftStore, UserStore}) => {
  return {
    gifts: GiftStore.gifts,
    setGifts: GiftStore.setGifts,
    bookGift: GiftStore.bookGift,
    canBookedGifts: GiftStore.canBookedGifts,
    loading: GiftStore.loading,
    setLoading: GiftStore.setLoading,
    user: UserStore.user
  };
};

export default magic(List, {store: mapStore, styles: s});
